package com.cognia.api.adapter.in.web;
import com.cognia.api.domain.service.*; import java.util.Map; import org.springframework.context.annotation.*; import org.springframework.boot.context.properties.ConfigurationProperties; import org.springframework.boot.context.properties.EnableConfigurationProperties;
@Configuration @EnableConfigurationProperties(PracticeConfiguration.MasterySettings.class) public class PracticeConfiguration { @Bean ActivityCorrectionService activityCorrectionService(){return new ActivityCorrectionService();} @Bean MasteryPolicy masteryPolicy(MasterySettings settings){return new RuleBasedMasteryPolicy(settings.getDifficultyWeights());} @ConfigurationProperties("diagnostic.mastery") public static class MasterySettings { private Map<Integer,Double> difficultyWeights=Map.of(); public Map<Integer,Double> getDifficultyWeights(){return difficultyWeights;} public void setDifficultyWeights(Map<Integer,Double> v){difficultyWeights=v;} } }
